CREATE PARTITION FUNCTION pf_Monthly (DATE)
    AS RANGE RIGHT FOR VALUES ('2026-01-01', '2026-02-01', '2026-03-01');

CREATE PARTITION SCHEME ps_Monthly
    AS PARTITION pf_Monthly ALL TO ([PRIMARY]);

CREATE TABLE dbo.Events (
    EventId BIGINT IDENTITY,
    EventDate DATE NOT NULL,
    Payload NVARCHAR(400),
    CONSTRAINT PK_Events PRIMARY KEY (EventDate, EventId)
) ON ps_Monthly(EventDate);

-- Monthly sliding window
ALTER PARTITION SCHEME ps_Monthly NEXT USED [PRIMARY];
ALTER PARTITION FUNCTION pf_Monthly() SPLIT RANGE ('2026-04-01');

ALTER TABLE dbo.Events SWITCH PARTITION 1 TO dbo.EventsArchive;
ALTER PARTITION FUNCTION pf_Monthly() MERGE RANGE ('2026-01-01');

-- Or just empty old partitions instantly:
TRUNCATE TABLE dbo.Events WITH (PARTITIONS (1));
